package ama.transcript;
import ama.contract.TaskContracts.*;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class PublicationPreparationRenewalTest {
    final TaskLease lease=new TaskLease("00000000-0000-0000-0000-000000000001",1,"WORKER",Instant.parse("2026-10-29T00:00:00Z"),new TaskSpec("KNOWLEDGE_PUBLISH_V1","KNOWLEDGE_PUBLISH",new SubjectRef("MEETING","meeting"),"a".repeat(64),new TypedRef("PUBLICATION","00000000-0000-0000-0000-000000000002"),"b".repeat(64),1,0,0,3));
    Map<String,Object> row(String id){return Map.of("id",id,"state","RUNNING","attempt",1L,"lease_owner","WORKER","expires_at","2026-10-29T00:00","input_fingerprint","fingerprint");}
    Map<String,List<Map<String,Object>>> original(){return Map.of("durable_task",List.of(row(lease.taskId())),"task_attempt",List.of(Map.of("attempt",1L)),"external_operation",List.of(),"external_execution",List.of());}
    Map<String,List<Map<String,Object>>> changed(String column,Object value){var copy=new HashMap<>(original());var row=new HashMap<>(copy.get("durable_task").getFirst());row.put("expires_at","2026-10-29T00:00:05");row.put(column,value);copy.put("durable_task",List.of(row));return copy;}
    @Test void admitsOnlyForwardExpiryOfTheExactLiveOwnerAndAttempt(){assertTrue(PublicationGraph.onlyOwnExpiryChanged(lease,original(),changed("expires_at","2026-10-29T00:00:05")));assertFalse(PublicationGraph.onlyOwnExpiryChanged(lease,original(),original()));}
    @Test void acceptsTheActualJdbcLocalDateTimeRepresentation(){var before=new HashMap<>(original());var old=new HashMap<>(before.get("durable_task").getFirst());old.put("expires_at",java.time.LocalDateTime.parse("2026-10-29T00:00"));before.put("durable_task",List.of(old));var after=new HashMap<>(before);var fresh=new HashMap<>(old);fresh.put("expires_at",java.time.LocalDateTime.parse("2026-10-29T00:00:05"));after.put("durable_task",List.of(fresh));assertTrue(PublicationGraph.onlyOwnExpiryChanged(lease,before,after));}
    @Test void rejectsEveryOtherOwnTaskChange(){for(var entry:Map.<String,Object>of("state","READY","attempt",2L,"lease_owner","other","input_fingerprint","new","id","different").entrySet())assertFalse(PublicationGraph.onlyOwnExpiryChanged(lease,original(),changed(entry.getKey(),entry.getValue())),entry.getKey());}
    @Test void rejectsBackwardMissingOrMalformedExpiry(){for(Object value:List.of("2026-10-28T23:59:59","not-a-time",42L))assertFalse(PublicationGraph.onlyOwnExpiryChanged(lease,original(),changed("expires_at",value)));var after=changed("expires_at","2026-10-29T00:00:05");var row=new HashMap<>(after.get("durable_task").getFirst());row.remove("expires_at");after.put("durable_task",List.of(row));assertFalse(PublicationGraph.onlyOwnExpiryChanged(lease,original(),after));}
    @Test void rejectsAnyOtherUnionChangeOrMissingTable(){for(String table:List.of("task_attempt","external_operation","external_execution")){var after=changed("expires_at","2026-10-29T00:00:05");after.put(table,List.of(Map.of("changed",true)));assertFalse(PublicationGraph.onlyOwnExpiryChanged(lease,original(),after),table);}var missing=changed("expires_at","2026-10-29T00:00:05");missing.remove("external_execution");assertFalse(PublicationGraph.onlyOwnExpiryChanged(lease,original(),missing));}
    @Test void rejectsUnrelatedTaskChangesAndAdditionalRows(){var before=new HashMap<>(original());before.put("durable_task",List.of(row(lease.taskId()),row("other-task")));var other=new HashMap<>(row("other-task"));other.put("expires_at","2026-10-29T00:00:05");var after=new HashMap<>(before);after.put("durable_task",List.of(row(lease.taskId()),other));assertFalse(PublicationGraph.onlyOwnExpiryChanged(lease,before,after));after.put("durable_task",List.of(changed("expires_at","2026-10-29T00:00:05").get("durable_task").getFirst(),other));assertFalse(PublicationGraph.onlyOwnExpiryChanged(lease,before,after));assertFalse(PublicationGraph.onlyOwnExpiryChanged(lease,original(),after));}
}
